def _parse_int(text: str) -> dict[str, int]:
    d: dict[str, int] = {}
    for line in text.split('\n'):
        if line != '':
            parts = line.split('=')
            d[parts[0]] = int(parts[1])
    return d


def _parse_bmp(text: str) -> dict[str, str]:
    d: dict[str, str] = {}
    for record in text.split('\x01'):
        if record != '':
            parts = record.split('\x00')
            d[parts[0]] = parts[1]
    return d


